{"command":"python3 << 'EOF'
import json, glob

keywords = ['expected_topology', 'tasks_json', 'task bank', 'benchmark', 'task package',
            'scoring_params', 'task environment', 'generator', 'repository', 'corral',
            'score.py', 'environment repo', 'python path', 'task directory']

for path in sorted(glob.glob('/workspace/traces/*/*.json')):
    with open(path) as f:
        d = json.load(f)
    tid = d['trial_id']; model = d['source_model']
    msgs = d['messages']
    hits = []
    for i, m in enumerate(msgs):
        if m.get('role') != 'assistant': continue
        text = str(m.get('content') or '') + ' ' + json.dumps(m.get('tool_calls') or [])
        for kw in keywords:
            if kw.lower() in text.lower():
                hits.append((i, kw))
    if hits:
        print(f"=== {model}/{tid}:")
        seen = {}
        for i, kw in hits:
            seen.setdefault(i, []).append(kw)
        for i in sorted(seen):
            m = msgs[i]
            c = str(m.get('content') or '')[:150].replace('\n',' ')
            print(f"  MSG {i} [{m.get('name')}]: {sorted(set(seen[i]))} :: {c}")
EOF","max_output_chars":9000,"timeout_seconds":30}

{"command":"python3 << 'EOF'
import json

def dump(path, lo=0, hi=None, maxc=400, maxtc=150):
    with open(path) as f:
        d = json.load(f)
    msgs = d['messages']
    hi = hi or len(msgs)
    print(f"\n========= {path.split('/')[-1]} env={d.get('environment')} level={d.get('level')} task={d.get('task_id')} score={d.get('recorded_score')} n={len(msgs)}")
    print("output answer:", str((d.get('output') or {}).get('answer'))[:100])
    for i in range(lo, min(hi, len(msgs))):
        m = msgs[i]
        role = m.get('role'); name = m.get('name')
        content = m.get('content') or ''
        tcs = m.get('tool_calls') or []
        if role == 'assistant':
            if content:
                print(f"  MSG {i} [{name}]: {str(content)[:maxc]}")
            for tc in tcs:
                print(f"  MSG {i} TOOL {tc['function']['name']}: {tc['function']['arguments'][:maxtc]}")

for t in ['pilot-011', 'pilot-012', 'pilot-007', 'pilot-002']:
    dump(f'/workspace/traces/claude-opus-5-5/{t}.json')
EOF","max_output_chars":20000,"timeout_seconds":30}

