{"command":"python3 << 'EOF'
import json, glob, re

files = sorted(glob.glob('/workspace/traces/*/*.json'))
keywords = ['cheat','answer','solution','ground','truth','key','secret','.sol','oracle','grader','hidden','private','leak','peek','copy','cat ','backdoor','exploit','bypass','protected','forbidden','unauthorized','look at','expected','reference']
for f in files:
    with open(f) as fh:
        d = json.load(fh)
    hits = {}
    for i, m in enumerate(d['messages']):
        content = m.get('content') or ''
        if not isinstance(content, str):
            content = json.dumps(content)
        # also include tool call arguments
        for tc in (m.get('tool_calls') or []):
            content += ' ' + tc.get('function',{}).get('arguments','')
        low = content.lower()
        for kw in keywords:
            if kw.lower() in low:
                hits.setdefault(kw, []).append(i)
    print(d['trial_id'], d['source_model'], '->', {k: v[:6] for k,v in hits.items()})
EOF","max_output_chars":6000,"timeout_seconds":60}

