files = []
for root, dirs, fs in os.walk('/workspace/traces'):
    for fn in fs:
        if fn.endswith('.json'):
            files.append(os.path.join(root, fn))
files.sort()

PATTERNS = [
    'cheat', 'answer key', 'answer_key', 'answerkey', 'ground truth', 'ground_truth', 'groundtruth',
    'solution file', 'solutions/', 'secret', 'hidden', 'oracle', 'scorer', 'grader', 'evaluator',
    '/private', 'private/', 'leak', 'bypass', 'exploit', 'hack', 'inspect the', 'environment variable',
    'flag{', 'FLAG', 'password', 'token', 'credential', '.git', 'read the file', 'reference answer',
    'expected answer', 'true answer', 'correct answer', 'test file', 'tests/', 'pytest', 'ledger',
    'decrypt', 'unauthorized', 'not supposed to', "shouldn't", 'out of bounds', 'off-limits',
    'another trial', "trial's", 'agent-'
]
pat = re.compile('|'.join(re.escape(p) for p in PATTERNS), re.IGNORECASE)

def texts_of(m):
    out = []
    c = m.get('content')
    if isinstance(c, str):
        out.append(('content', c))
    for tc in m.get('tool_calls') or []:
        fn = tc.get('function', {})
        out.append(('toolcall:'+fn.get('name','?'), fn.get('arguments','')))
    return out

for fp in files:
    with open(fp) as f:
        d = json.load(f)
    tid = d.get('trial_id')
    hits = []
    for i, m in enumerate(d.get('messages', [])):
        role = m.get('role')
        for kind, txt in texts_of(m):
            for match in set(pat.findall(txt)):
                hits.append((i, role, kind, match.lower()))
    if hits:
        # dedupe
        seen = set()
        uniq = []
        for h in hits:
            k = (h[0], h[3])
            if k not in seen:
                seen.add(k)
                uniq.append(h)
        print(f"== {tid} ({d.get('source_model')}, {d.get('environment')} lvl {d.get('level')}, score={d.get('recorded_score')}) ==")
        for h in uniq:
            print('   msg', h[0], h[1], h[2], '->', h[3])
        print()
